export type ParsedBuyInstruction<
  TProgram extends string = typeof ONCE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    buyer: TAccountMetas[0];
    config: TAccountMetas[1];
    call: TAccountMetas[2];
    vault: TAccountMetas[3];
    mint: TAccountMetas[4];
    tokenProgram: TAccountMetas[5];
    usdcMint: TAccountMetas[6];
    usdcTokenProgram: TAccountMetas[7];
    paymentSource: TAccountMetas[8];
    paymentDestination: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: BuyInstructionData;
};

export function parseBuyInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBuyInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      buyer: getNextAccount(),
      config: getNextAccount(),
      call: getNextAccount(),
      vault: getNextAccount(),
      mint: getNextAccount(),
      tokenProgram: getNextAccount(),
      usdcMint: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      paymentSource: getNextAccount(),
      paymentDestination: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getBuyInstructionDataDecoder().decode(instruction.data),
  };
}
